from itertools import combinations

def girth_at_least_6(adj, n):
    # BFS from each vertex to find shortest cycle
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            new = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        new.append(v)
                    elif parent[u] != v and parent[v] != u:
                        # cycle found
                        if dist[u] + dist[v] + 1 < 6:
                            return False
            queue = new
    return True

