import random

def girth_at_least_6_after(adj, u, v):
    # returns True if adding edge u-v keeps girth >= 6, i.e., current dist(u,v) >= 5
    if v in adj[u]:
        return False
    # BFS from u, limit 4
    dist = {u: 0}
    q = [u]
    for d in range(1, 5):
        nq = []
        for x in q:
            for y in adj[x]:
                if y not in dist:
                    dist[y] = d
                    if y == v:
                        return False
                    nq.append(y)
        q = nq
    return True

def build(n, deg_target, seed):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = []
    # Keep adding edges, randomly, as long as possible
    for _ in range(10000):
        # all potential (u,v) with both degrees < deg_target and girth ok
        available = [i for i in range(n) if len(adj[i]) < deg_target]
        if len(available) < 2:
            break
        random.shuffle(available)
        added = False
        # try pairs
        for i in range(len(available)):
            u = available[i]
            for j in range(i+1, len(available)):
                v = available[j]
                if girth_at_least_6_after(adj, u, v):
                    adj[u].add(v)
                    adj[v].add(u)
                    edges.append((min(u,v), max(u,v)))
                    added = True
                    break
            if added:
                break
        if not added:
            break
    return edges, adj

